{"packet_id":"D034-01","doc_id":"D034","jurisdiction":"Hoboken, NJ","category":"rent_increase_limits","lifecycle":"enacted","title":"Hoboken mandatory disclosures for rent increases over 10%","requirement":"A landlord seeking to raise rent by more than 10% on renewal of a current tenant's lease must give the tenant an itemized cost breakdown, disclosure of whether a rent algorithm was used, notice of the right to take legal action, and the Division of Housing's contact information.","key_value":"10%","coverage_conditions":"All residential landlords in Hoboken seeking to increase rent by more than 10% upon renewal of a lease with a current tenant year over year.","applicability":{"conditions":[],"per_tenancy":"Rent increase of more than 10% upon renewal of a lease with a current tenant year over year","coverage_quotes":[]},"exemptions":null,"penalty":"A fine not exceeding $1,000 per incident for a landlord who pleads guilty or is found guilty of failing to provide the required disclosures.","effective_date":null,"valid_through":null,"citation":"Hoboken Mun. Code § 158-1","quoted_span":"All residential landlords seeking to increase rent by more than 10% upon a renewal of a lease with a current tenant year over year shall be required to make the following disclosures to existing tenants either in the lease upon renewal (must be clearly indicated on the first page) or on a form provided by the Hoboken Division of Housing prior to the increase being implemented:","interaction":null,"relations":[],"confidence":0.95,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D034-01","doc_id":"D034","jurisdiction":"Hoboken, NJ","category":"algorithmic_rent_setting","lifecycle":"enacted","title":"Hoboken algorithmic rent fixing prohibition","requirement":"Landlords renting residential dwelling units in Hoboken may not price fix using algorithmic pricing: software, algorithms or data-sharing platforms that collect and analyze nonpublic competitor information to coordinate, recommend or implement rents, lease terms or occupancy levels.","key_value":null,"coverage_conditions":"Landlords who rent any residential dwelling unit (any primary residence excluding medical/long-term care or detention facilities) in the City of Hoboken.","applicability":{"conditions":[],"per_tenancy":null,"coverage_quotes":[]},"exemptions":"Medical/long-term care or detention facilities are excluded from the definition of residential dwelling unit.","penalty":"Upon conviction: penalties as prescribed under N.J.S.A. 40:49-5, or a fine not exceeding $2,000, or community service not exceeding 90 days.","effective_date":null,"valid_through":null,"citation":"Hoboken Mun. Code § 158-2","quoted_span":"Landlords who rent any residential dwelling unit (defined as any primary residence excluding medical/long-term care or detention facilities) in the City of Hoboken are prohibited from price fixing using algorithmic pricing.","interaction":null,"relations":[],"confidence":0.95,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D034-01","n_rules":2,"note":null}

